  'about.whatIsTitle': 'What is Krishi Sangam?',
  'about.whatIsBody': 'Krishi Sangam is a comprehensive digital agriculture platform designed to connect every part of the farming ecosystem through one trusted platform. We bring together farmers, landowners, equipment providers, agricultural labourers, service providers, and produce buyers, making it easier to access essential farming resources without unnecessary delays or middlemen.\n\nOur platform simplifies agricultural operations by offering services such as land leasing, farm equipment rentals, skilled agricultural labour, and a transparent marketplace for buying and selling produce. By connecting verified users and trusted businesses, Krishi Sangam helps farmers save time, reduce operational costs, increase productivity, and make informed decisions throughout every stage of farming.\n\nWhether managing a small family farm or a large agricultural enterprise, Krishi Sangam provides modern digital solutions that make farming more efficient, affordable, and accessible for everyone.',
  'about.mission': 'Our Mission',
  'about.missionBody': 'To empower farmers with easy access to land, machinery, labour, and future agricultural services through a reliable, technology-driven platform that improves efficiency, reduces operational challenges, and supports long-term growth.',
  'about.impact': 'Impact We Want to Create',
  'about.impactBody': 'To become India’s most trusted agricultural ecosystem by connecting every stakeholder in the farming value chain through technology.',
  'about.founder': 'Meet the Founder',
  'about.founderName': 'Rushabh Jadhav',
  'about.founderTitle': 'Founder, Krishi Setu',
  'about.founderP1': 'Raised with deep roots in agriculture, Rushabh founded Krishi Setu to address the everyday challenges faced by India’s farming community. His paternal grandfather served as an Agriculture Officer, while his maternal grandfather was both a farmer and Chairman of the Agricultural Produce Market Committee (APMC). Growing up around farming and the agricultural ecosystem gave him firsthand insight into the challenges faced by farmers, landowners, and agricultural service providers.',
  'about.founderP2': 'Combining his background in Business Analytics with his passion for technology and agriculture, Rushabh founded Krishi Setu with a vision to build a trusted digital platform that simplifies land leasing, farm equipment rentals, and agricultural services, while creating a connected ecosystem for Indian agriculture.',
