  'chatbot.greeting': '👋 Welcome to Krishi Sangam! How can I help you today?',
  'chatbot.greetingLoggedIn': '👋 Welcome back, {name}! How can I help you today?',
  'chatbot.suggestion': 'You can type a question or tap one of the quick topics below.',
  'chatbot.statusOnline': 'Online',
  'chatbot.notifText': '👋 Hi! I\'m the Krishi Sangam chatbot — take help from me!',
