  'home.sellTitle': 'अपनी उपज बेचें',
  'home.sellBody': 'सत्यापित खरीदारों से सीधे जुड़ें और स्थानीय मंडियों से परे अपना बाजार बढ़ाएं। कृषि संगम किसानों को अपनी फसल दिखाने, प्रतिस्पर्धी ऑफर पाने, बेहतर कीमतों पर बातचीत करने और अधिक पारदर्शिता के साथ बेचने में सक्षम बनाता है। हमारा मंच बिचौलियों पर निर्भरता कम करते हुए किसानों के मुनाफे को अधिकतम करने में मदद करता है।',
