  'about.missionBody': 'एक विश्वसनीय, प्रौद्योगिकी-संचालित मंच के माध्यम से किसानों को भूमि, मशीनरी, श्रम और भविष्य की कृषि सेवाओं तक आसान पहुंच प्रदान करना जो दक्षता में सुधार करे, परिचालन चुनौतियों को कम करे और दीर्घकालिक विकास का समर्थन करे।',
  'about.founderTitle': 'संस्थापक, कृषि सेतु',
  'about.founderP1': 'कृषि में गहरी जड़ों के साथ पले-बढ़े, ऋषभ ने भारत के कृषि समुदाय की रोज़मर्रा की चुनौतियों का समाधान करने के लिए कृषि सेतु की स्थापना की। उनके दादा कृषि अधिकारी थे, जबकि उनके नाना किसान और कृषि उपज बाजार समिति (APMC) के अध्यक्ष दोनों थे।',
