  'chatbot.faq1_q': 'कृषि संगम क्या है?',
  'chatbot.faq1_a': 'कृषि संगम एक डिजिटल कृषि मंच है जो किसानों को भूमि मालिकों, उपकरण प्रदाताओं, मज़दूरों और खरीदारों से जोड़ता है — सब एक ही जगह।',
  'chatbot.faq2_q': 'क्या यह मंच मुफ़्त है?',
  'chatbot.faq2_a': 'हाँ! कृषि संगम पर साइन अप और सेवाएं ब्राउज़ करना पूरी तरह मुफ़्त है।',
  'chatbot.faq3_q': 'मैं भूमि कैसे पट्टे पर ले सकता हूँ?',
  'chatbot.faq3_a': 'आप हमारे भूमि पट्टा पृष्ठ पर उपलब्ध भूमि लिस्टिंग ब्राउज़ कर सकते हैं।',
  'chatbot.faq4_q': 'क्या मैं कृषि उपकरण किराये पर ले सकता हूँ?',
  'chatbot.faq4_a': 'बिल्कुल! हमारे उपकरण किराया अनुभाग में सत्यापित मालिकों से ट्रैक्टर, हार्वेस्टर, रोटावेटर, स्प्रेयर सूचीबद्ध हैं।',
  'chatbot.faq5_q': 'मैं कृषि मज़दूर कैसे रख सकता हूँ?',
  'chatbot.faq5_a': 'श्रम टीम बुक करने के लिए हमारे कृषि सेवा पृष्ठ पर जाएं।',
  'chatbot.faq6_q': 'मेरे लेनदेन कैसे सुरक्षित हैं?',
  'chatbot.faq6_a': 'कृषि संगम भुगतान के लिए एस्क्रो प्रणाली का उपयोग करता है। सेवा पूरी होने तक आपका भुगतान सुरक्षित रूप से रखा जाता है।',
  'chatbot.faq6_f1_q': 'विश्वास जमा प्रणाली क्या है?',
  'chatbot.faq6_f1_a': 'हमारी विश्वास प्रणाली में तीन स्तर हैं: नया उपयोगकर्ता (पूरी जमा), विश्वसनीय (3 किराये के बाद 50% जमा), और प्राथमिकता (10 किराये के बाद प्राथमिकता बुकिंग)।',
  'chatbot.faq6_f2_q': 'एस्क्रो कैसे काम करता है?',
  'chatbot.faq6_f2_a': 'जब आप बुकिंग करते हैं, तो आपका भुगतान एस्क्रो में रखा जाता है। भुगतान केवल तभी सेवा प्रदाता को जारी किया जाता है जब दोनों पक्ष काम पूरा होने की पुष्टि करते हैं।',
  'chatbot.faq7_q': 'मैं अपनी उपज कैसे बेच सकता हूँ?',
  'chatbot.faq7_a': 'आप हमारे उपज बाज़ार पर अपनी फसल सूचीबद्ध कर सकते हैं।',
  'chatbot.faq8_q': 'मैं ताज़ी उपज कहाँ से खरीद सकता हूँ?',
  'chatbot.faq8_a': 'किसानों द्वारा सीधे सूचीबद्ध ताज़ी फसलें खोजने के लिए हमारे उपज बाज़ार पर ब्राउज़ करें।',
  'chatbot.faq9_q': 'मैं खाता कैसे बनाऊं?',
  'chatbot.faq9_a': 'ऊपर दाईं ओर "साइन अप" बटन पर क्लिक करें।',
  'chatbot.faq10_q': 'क्या मेरी व्यक्तिगत जानकारी सुरक्षित है?',
  'chatbot.faq10_a': 'हाँ, हम आपकी गोपनीयता को गंभीरता से लेते हैं। सभी उपयोगकर्ता डेटा एन्क्रिप्टेड और सुरक्षित रूप से संग्रहीत है।',
  'chatbot.faq11_q': 'मैं सहायता से कैसे संपर्क कर सकता हूँ?',
