  'nav.home': 'హోమ్',
  'nav.services': 'సేవలు',
  'nav.contact': 'సంప్రదించండి',
  'home.aboutTitle': 'కృషి సంగం గురించి',
  'home.aboutP1': 'కృషి సంగం అనేది వ్యవసాయ పర్యావరణ వ్యవస్థలోని ప్రతి భాగాన్ని ఒక నమ్మకమైన వేదిక ద్వారా కలపడానికి రూపొందించిన సమగ్ర డిజిటల్ వ్యవసాయ వేదిక. మేము రైతులు, భూయజమానులు, పరికరాల ప్రదాతలు, వ్యవసాయ కూలీలు, సేవా ప్రదాతలు మరియు పంట కొనుగోలుదారులను ఒకచోట చేర్చుతాము, తద్వారా అనవసరమైన జాప్యాలు లేదా మధ్యవర్తులు లేకుండా అవసరమైన వ్యవసాయ వనరులను పొందడం సులభమవుతుంది.',
  'home.aboutP2': 'మా వేదిక భూమి లీజు, వ్యవసాయ పరికరాల అద్దె, నైపుణ్యం కలిగిన వ్యవసాయ కూలీలు మరియు పంటల కొనుగోలు-విక్రయానికి పారదర్శక మార్కెట్ వంటి సేవలను అందించడం ద్వారా వ్యవసాయ కార్యకలాపాలను సులభతరం చేస్తుంది. ధృవీకరించబడిన వినియోగదారులు మరియు విశ్వసనీయ వ్యాపారాలను కలపడం ద్వారా, కృషి సంగం రైతులు సమయం ఆదా చేయడానికి, నిర్వహణ ఖర్చులను తగ్గించడానికి, ఉత్పాదకతను పెంచడానికి మరియు వ్యవసాయంలో ప్రతి దశలో సమాచారం ఆధారిత నిర్ణయాలు తీసుకోవడానికి సహాయపడుతుంది.',
  'home.aboutP3': 'చిన్న కుటుంబ పొలం అయినా లేదా పెద్ద వ్యవసాయ సంస్థ అయినా, కృషి సంగం ఆధునిక డిజిటల్ పరిష్కారాలను అందిస్తుంది, ఇవి వ్యవసాయాన్ని అందరికీ మరింత సమర్థవంతంగా, సరసమైనవిగా మరియు అందుబాటులో ఉంచుతాయి.',
  'home.aboutCta': 'మా గురించి మరింత తెలుసుకోండి',
