  'home.sellBody': 'ధృవీకరించబడిన కొనుగోలుదారులతో నేరుగా కనెక్ట్ అవ్వండి మరియు స్థానిక మండీలకు మించి మీ మార్కెట్ను విస్తరించండి. కృషి సంగం రైతులు తమ పంటలను ప్రదర్శించడానికి, పోటీ ఆఫర్లను పొందడానికి, మెరుగైన ధరలకు చర్చించడానికి మరియు ఎక్కువ పారదర్శకతతో విక్రయించడానికి వీలు కల్పిస్తుంది. మా వేదిక మధ్యవర్తులపై ఆధారపడటాన్ని తగ్గించి రైతుల లాభాలను పెంచడానికి సహాయపడుతుంది.',
