  'home.ctaTitle': 'వ్యవసాయ భవిష్యత్తులో చేరండి',
  'home.ctaBody': 'మీరు రైతు, భూయజమాని, పరికరాల యజమాని లేదా వ్యవసాయ సేవా ప్రదాత అయినా, కృషి సంగం మిమ్మల్ని కనెక్ట్ అవ్వడానికి, ఎదగడానికి మరియు విజయం సాధించడానికి సహాయపడుతుంది.',
