  'auth.optional': 'விருப்பம்',
  'home.hero.title': 'விவசாயிகள், வாங்குபவர்கள் மற்றும் வேளாண் சேவைகளுக்கான இந்தியாவின் டிஜிட்டல் பாலம்',
  'home.hero.subtitle': 'கிருஷி சங்கம் விவசாயிகளை சரிபார்க்கப்பட்ட வாங்குபவர்கள், வேளாண் இயந்திரங்கள், வேளாண் சேவைகள், சேமிப்பு தீர்வுகள், நிதி உதவி மற்றும் நிபுணர் வழிகாட்டுதலுடன் இணைக்கிறது.',
  'home.getStarted': 'தொடங்குங்கள்',
  'home.exploreServices': 'சேவைகளை ஆராயுங்கள்',
  'home.whatIsTitle': 'கிருஷி சங்கம் என்றால் என்ன?',
  'home.agriSimple': 'வேளாண்மை எளிமையானது.',
  'home.whatIsBody': 'கிருஷி சங்கம் என்பது விவசாயிகளை நம்பகமான நில குத்தகை, உபகரணங்கள் மற்றும் சேவைகளுடன் இணைக்கும் டிஜிட்டல் தளம்.',
  'home.offerTitle': 'இன்று நாங்கள் வழங்குவது',
  'home.landLeasing': 'நில குத்தகை',
  'home.landLeasingBody': 'வெளிப்படைத்தன்மையுடன் வேளாண் நிலத்தை குத்தகைக்கு விட நில உரிமையாளர்களையும் விவசாயிகளையும் பாதுகாப்பான தளத்தில் இணைக்கவும்.',
  'home.equipmentRental': 'உபகரண வாடகை',
  'home.equipmentRentalBody': 'சரிபார்க்கப்பட்ட உரிமையாளர்களிடமிருந்து டிராக்டர், அறுவடை இயந்திரம், ரோட்டாவேட்டர், விதைத்தூவி மற்றும் பிற வேளாண் இயந்திரங்களைப் பெறுங்கள்.',
  'home.labourServices': 'வேளாண் கூலிகள் மற்றும் பண்ணை சேவைகள்',
  'home.labourServicesBody': 'விதைப்பு, அறுவடை, தெளித்தல், பாசனம் போன்றவற்றுக்கு நம்பகமான வேளாண் கூலிகள் மற்றும் சேவை வழங்குநர்களை ஒரே இடத்தில் கண்டறியுங்கள்.',
  'home.comingSoon': 'விரைவில்',
  'home.comingSoonBody': 'கிருஷி சங்கம் இந்தியாவின் முழுமையான வேளாண் சூழலமைப்பாக உருவாக தொடர்ந்து விரிவடைகிறது. வரவிருக்கும் சேவைகள்:',
  'home.coming.seeds': 'விதைகள், உரங்கள் மற்றும் வேளாண் உள்ளீடுகள்',
  'home.coming.marketplace': 'பயிர் வாங்க-விற்பனை சந்தை',
  'home.coming.storage': 'சேமிப்பு மற்றும் குளிர்ச்சி சங்கிலி தளவாடங்கள்',
  'home.coming.finance': 'நிதி உதவி, கடன்கள் மற்றும் காப்பீடு',
  'home.coming.advisory': 'நிபுணர் வேளாண் ஆலோசனை',
  'home.whyChoose': 'விவசாயிகள் ஏன் கிருஷி சங்கம்வை தேர்வு செய்கிறார்கள்',
  'home.verified': 'சரிபார்க்கப்பட்ட நெட்வொர்க்',
  'home.verifiedBody': 'அதிக நம்பிக்கை மற்றும் வெளிப்படைத்தன்மைக்கு ஒவ்வொரு சேவை வழங்குநரும் சரிபார்ப்புக்கு உட்படுகிறார்.',
  'home.saveTime': 'நேரத்தை சேமிக்கவும்',
  'home.saveTimeBody': 'இயந்திரங்கள், கூலிகள் மற்றும் வேளாண் சேவைகளைத் தேடுவதில் செலவிடும் முயற்சியைக் குறைக்கவும்.',
  'home.builtForEvery': 'ஒவ்வொரு விவசாயிக்கும்',
  'home.builtForEveryBody': 'உங்களிடம் 2 ஏக்கர் அல்லது 200 ஏக்கர் இருந்தாலும், கிருஷி சங்கம் ஒவ்வொரு அளவிலான பண்ணைக்கும் வடிவமைக்கப்பட்டுள்ளது.',
  'home.howItWorks': 'இது எப்படி செயல்படுகிறது',
  'home.step1': 'உங்கள் இலவச கணக்கை உருவாக்குங்கள்.',
  'home.step2': 'உங்களுக்குத் தேவையான சேவையைத் தேர்ந்தெடுக்கவும்.',
  'home.step3': 'சரிபார்க்கப்பட்ட வழங்குநர்களுடன் இணையுங்கள்.',
  'home.step4': 'பரிவர்த்தனையை பாதுகாப்பாக முடிக்கவும்.',
  'home.step5': 'உங்கள் அனுபவத்தை மதிப்பிடுங்கள்.',
  'home.ctaTitle': 'வேளாண்மையின் எதிர்காலத்தில் இணையுங்கள்',
  'home.ctaBody': 'நீங்கள் விவசாயியாகவோ, நில உரிமையாளராகவோ, உபகரண உரிமையாளராகவோ அல்லது வேளாண் சேவை வழங்குநராகவோ இருந்தாலும், கிருஷி சங்கம் இணையவும், வளரவும், வெற்றி பெறவும் உதவுகிறது.',
  'home.ctaButton': 'இன்றே தொடங்குங்கள்',
  'home.footer.tagline': 'முழுமையான டிஜிட்டல் வேளாண் சூழலமைப்புடன் விவசாயிகளை மேம்படுத்துதல்.',
