  'home.footer.phone': 'தொலைபேசி:',
  'home.footer.email': 'மின்னஞ்சல்:',
  'home.footer.rights': '© 2026 கிருஷி சங்கம். அனைத்து உரிமைகளும் பாதுகாக்கப்பட்டவை.',
  'about.title': 'எங்களை பற்றி',
  'about.subtitle': 'கிருஷி சங்கம்வின் பின்னணியில் உள்ள பார்வை, நோக்கம் மற்றும் மக்களைக் கண்டறியுங்கள்.',
  'about.whatIsTitle': 'கிருஷி சங்கம் என்றால் என்ன?',
  'about.whatIsBody': 'கிருஷி சங்கம் விவசாயிகளை நம்பகமான நில குத்தகை, வேளாண் உபகரணங்கள் மற்றும் வேளாண் சேவைகளுடன் இணைக்கும் டிஜிட்டல் தளம்.',
  'about.mission': 'எங்கள் நோக்கம்',
  'about.impact': 'நாங்கள் உருவாக்க விரும்பும் தாக்கம்',
  'about.impactBody': 'தொழில்நுட்பம் மூலம் வேளாண் மதிப்பு சங்கிலியில் உள்ள ஒவ்வொரு பங்குதாரரையும் இணைத்து இந்தியாவின் மிகவும் நம்பகமான வேளாண் சூழலமைப்பாக மாறுவது.',
