  'chatbot.faq1_q': 'கிருஷி சங்கம் என்றால் என்ன?',
  'chatbot.faq1_a': 'கிருஷி சங்கம் விவசாயிகளை நில உரிமையாளர்கள், உபகரண வழங்குநர்கள், தொழிலாளர்கள் மற்றும் வாங்குபவர்களுடன் இணைக்கும் டிஜிட்டல் விவசாய தளம்.',
  'chatbot.faq2_q': 'இந்த தளம் இலவசமா?',
  'chatbot.faq2_a': 'ஆம்! பதிவு செய்வதும் சேவைகளை உலாவுவதும் முற்றிலும் இலவசம்.',
  'chatbot.faq3_q': 'நிலத்தை குத்தகைக்கு எடுப்பது எப்படி?',
  'chatbot.faq3_a': 'எங்கள் நிலக் குத்தகை பக்கத்தில் கிடைக்கும் பட்டியல்களை உலாவுங்கள்.',
  'chatbot.faq4_q': 'விவசாய உபகரணங்களை வாடகைக்கு எடுக்க முடியுமா?',
  'chatbot.faq4_a': 'நிச்சயமாக! எங்கள் உபகரண வாடகை பிரிவில் சரிபார்க்கப்பட்ட உரிமையாளர்களிடம் இருந்து உபகரணங்கள் பட்டியலிடப்பட்டுள்ளன.',
  'chatbot.faq5_q': 'விவசாய தொழிலாளர்களை எப்படி நியமிப்பது?',
  'chatbot.faq5_a': 'தொழிலாளர் குழுவை முன்பதிவு செய்ய எங்கள் விவசாய சேவைகள் பக்கத்திற்கு செல்லுங்கள்.',
  'chatbot.faq6_q': 'என் பரிவர்த்தனைகள் எப்படி பாதுகாக்கப்படுகின்றன?',
  'chatbot.faq6_a': 'கிருஷி சங்கம் கட்டணங்களுக்கு எஸ்க்ரோ முறையைப் பயன்படுத்துகிறது.',
  'chatbot.faq6_f1_q': 'நம்பிக்கை வைப்பு முறை என்ன?',
  'chatbot.faq6_f1_a': 'மூன்று நிலைகள்: புதிய பயனர் (முழு வைப்பு), நம்பகமான (50% வைப்பு), முன்னுரிமை (முன்னுரிமை முன்பதிவு).',
  'chatbot.faq6_f2_q': 'எஸ்க்ரோ எப்படி செயல்படுகிறது?',
  'chatbot.faq6_f2_a': 'முன்பதிவு செய்யும்போது உங்கள் கட்டணம் எஸ்க்ரோவில் வைக்கப்படும். இரு தரப்பும் உறுதிப்படுத்திய பின்னரே வழங்குநருக்கு வெளியிடப்படும்.',
  'chatbot.faq7_q': 'என் விளைபொருளை எப்படி விற்பது?',
  'chatbot.faq7_a': 'எங்கள் விளைபொருள் சந்தையில் உங்கள் பயிர்களை பட்டியலிடுங்கள்.',
  'chatbot.faq8_q': 'புதிய விளைபொருளை எங்கே வாங்கலாம்?',
  'chatbot.faq8_a': 'எங்கள் விளைபொருள் சந்தையை உலாவுங்கள்.',
  'chatbot.faq9_q': 'கணக்கை எப்படி உருவாக்குவது?',
  'chatbot.faq9_a': 'மேல் வலதுபுறம் "பதிவு" பொத்தானைக் கிளிக் செய்யுங்கள்.',
  'chatbot.faq10_q': 'என் தனிப்பட்ட தகவல் பாதுகாப்பானதா?',
  'chatbot.faq10_a': 'ஆம், அனைத்து தரவும் குறியாக்கம் செய்யப்பட்டு பாதுகாப்பாக சேமிக்கப்படுகிறது.',
  'chatbot.faq11_q': 'ஆதரவை எப்படி தொடர்பு கொள்வது?',
  'chatbot.faq11_a': '+91-8828473778 அல்லது jaijaikuber@gmail.com மூலம் தொடர்பு கொள்ளுங்கள்.',
  'chatbot.faq11_f1_q': 'உங்கள் ஆதரவு நேரம் என்ன?',
  'chatbot.faq11_f1_a': 'திங்கள் முதல் சனி, காலை 9 முதல் மாலை 6 IST.',
  'chatbot.faq12_q': 'என் முன்பதிவுகளை எப்படி சரிபார்ப்பது?',
  'chatbot.faq12_a': 'சுயவிவர மெனுவிலிருந்து "என் முன்பதிவுகள்" பக்கத்திற்கு செல்லுங்கள்.',
