  'home.aboutP1': 'ਕ੍ਰਿਸ਼ੀ ਸੰਗਮ ਇੱਕ ਵਿਆਪਕ ਡਿਜੀਟਲ ਖੇਤੀਬਾੜੀ ਪਲੇਟਫਾਰਮ ਹੈ ਜੋ ਖੇਤੀ ਈਕੋਸਿਸਟਮ ਦੇ ਹਰ ਹਿੱਸੇ ਨੂੰ ਇੱਕ ਭਰੋਸੇਮੰਦ ਪਲੇਟਫਾਰਮ ਰਾਹੀਂ ਜੋੜਨ ਲਈ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ। ਅਸੀਂ ਕਿਸਾਨਾਂ, ਜ਼ਮੀਨ ਮਾਲਕਾਂ, ਸਾਜ਼ੋ-ਸਾਮਾਨ ਪ੍ਰਦਾਤਾਵਾਂ, ਖੇਤੀ ਮਜ਼ਦੂਰਾਂ, ਸੇਵਾ ਪ੍ਰਦਾਤਾਵਾਂ ਅਤੇ ਫ਼ਸਲ ਖਰੀਦਦਾਰਾਂ ਨੂੰ ਇਕੱਠੇ ਲਿਆਉਂਦੇ ਹਾਂ, ਤਾਂ ਜੋ ਬੇਲੋੜੀ ਦੇਰੀ ਜਾਂ ਵਿਚੋਲਿਆਂ ਤੋਂ ਬਿਨਾਂ ਜ਼ਰੂਰੀ ਖੇਤੀ ਸਰੋਤਾਂ ਤੱਕ ਪਹੁੰਚ ਆਸਾਨ ਹੋਵੇ।',
  'home.aboutP2': 'ਸਾਡਾ ਪਲੇਟਫਾਰਮ ਜ਼ਮੀਨ ਲੀਜ਼, ਖੇਤੀ ਸਾਜ਼ੋ-ਸਾਮਾਨ ਕਿਰਾਏ, ਹੁਨਰਮੰਦ ਖੇਤੀ ਮਜ਼ਦੂਰ ਅਤੇ ਫ਼ਸਲ ਖਰੀਦਣ-ਵੇਚਣ ਲਈ ਪਾਰਦਰਸ਼ੀ ਬਾਜ਼ਾਰ ਵਰਗੀਆਂ ਸੇਵਾਵਾਂ ਦੇ ਕੇ ਖੇਤੀ ਕਾਰਜਾਂ ਨੂੰ ਸਰਲ ਬਣਾਉਂਦਾ ਹੈ। ਪ੍ਰਮਾਣਿਤ ਉਪਭੋਗਤਾਵਾਂ ਅਤੇ ਭਰੋਸੇਮੰਦ ਕਾਰੋਬਾਰਾਂ ਨੂੰ ਜੋੜ ਕੇ, ਕ੍ਰਿਸ਼ੀ ਸੰਗਮ ਕਿਸਾਨਾਂ ਨੂੰ ਸਮਾਂ ਬਚਾਉਣ, ਕਾਰਜਸ਼ੀਲ ਲਾਗਤ ਘਟਾਉਣ, ਉਤਪਾਦਕਤਾ ਵਧਾਉਣ ਅਤੇ ਖੇਤੀ ਦੇ ਹਰ ਪੜਾਅ ਵਿੱਚ ਸੂਚਿਤ ਫੈਸਲੇ ਲੈਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ।',
  'home.aboutP3': 'ਭਾਵੇਂ ਛੋਟਾ ਪਰਿਵਾਰਕ ਫਾਰਮ ਹੋਵੇ ਜਾਂ ਵੱਡਾ ਖੇਤੀ ਉੱਦਮ, ਕ੍ਰਿਸ਼ੀ ਸੰਗਮ ਆਧੁਨਿਕ ਡਿਜੀਟਲ ਹੱਲ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ ਜੋ ਖੇਤੀ ਨੂੰ ਹਰ ਕਿਸੇ ਲਈ ਵਧੇਰੇ ਕੁਸ਼ਲ, ਕਿਫਾਇਤੀ ਅਤੇ ਪਹੁੰਚਯੋਗ ਬਣਾਉਂਦੇ ਹਨ।',
  'home.aboutCta': 'ਸਾਡੇ ਬਾਰੇ ਹੋਰ ਜਾਣੋ',
  'home.visionTitle': 'ਸਾਡਾ ਦ੍ਰਿਸ਼ਟੀਕੋਣ',
  'home.sellTitle': 'ਆਪਣੀ ਫ਼ਸਲ ਵੇਚੋ',
  'home.sellBody': 'ਪ੍ਰਮਾਣਿਤ ਖਰੀਦਦਾਰਾਂ ਨਾਲ ਸਿੱਧਾ ਜੁੜੋ ਅਤੇ ਸਥਾਨਕ ਮੰਡੀਆਂ ਤੋਂ ਅੱਗੇ ਆਪਣਾ ਬਾਜ਼ਾਰ ਵਧਾਓ। ਕ੍ਰਿਸ਼ੀ ਸੰਗਮ ਕਿਸਾਨਾਂ ਨੂੰ ਆਪਣੀਆਂ ਫ਼ਸਲਾਂ ਦਿਖਾਉਣ, ਮੁਕਾਬਲੇ ਵਾਲੀਆਂ ਪੇਸ਼ਕਸ਼ਾਂ ਪ੍ਰਾਪਤ ਕਰਨ, ਬਿਹਤਰ ਕੀਮਤਾਂ \'ਤੇ ਗੱਲਬਾਤ ਕਰਨ ਅਤੇ ਵਧੇਰੇ ਪਾਰਦਰਸ਼ਤਾ ਨਾਲ ਵੇਚਣ ਦੇ ਯੋਗ ਬਣਾਉਂਦਾ ਹੈ। ਸਾਡਾ ਪਲੇਟਫਾਰਮ ਵਿਚੋਲਿਆਂ \'ਤੇ ਨਿਰਭਰਤਾ ਘਟਾ ਕੇ ਕਿਸਾਨਾਂ ਦੇ ਮੁਨਾਫ਼ੇ ਨੂੰ ਵੱਧ ਤੋਂ ਵੱਧ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ।',
  'home.sellCta': 'ਫ਼ਸਲ ਵੇਚੋ',
  'home.comingSoonSub': 'ਕ੍ਰਿਸ਼ੀ ਸੰਗਮ ਭਾਰਤ ਦਾ ਸੰਪੂਰਨ ਡਿਜੀਟਲ ਖੇਤੀ ਈਕੋਸਿਸਟਮ ਬਣਨ ਲਈ ਲਗਾਤਾਰ ਵਿਸਤਾਰ ਕਰ ਰਿਹਾ ਹੈ।',
