  'home.whyTitle': 'ਕਿਸਾਨ ਕ੍ਰਿਸ਼ੀ ਸੰਗਮ ਨੂੰ ਕਿਉਂ ਚੁਣਦੇ ਹਨ',
  'home.why1Title': 'ਪ੍ਰਮਾਣਿਤ ਨੈੱਟਵਰਕ',
  'home.why1Body': 'ਵਿਸ਼ਵਾਸ, ਪਾਰਦਰਸ਼ਤਾ ਅਤੇ ਸੁਰੱਖਿਅਤ ਲੈਣ-ਦੇਣ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ ਹਰ ਕਿਸਾਨ, ਜ਼ਮੀਨ ਮਾਲਕ, ਸਾਜ਼ੋ-ਸਾਮਾਨ ਪ੍ਰਦਾਤਾ, ਖਰੀਦਦਾਰ ਅਤੇ ਸੇਵਾ ਭਾਈਵਾਲ ਪ੍ਰਮਾਣਿਤ ਹੈ।',
