  'home.why5Title': 'ਹਰ ਕਿਸਾਨ ਲਈ ਬਣਾਇਆ ਗਿਆ',
  'home.why5Body': 'ਭਾਵੇਂ ਤੁਹਾਡੇ ਕੋਲ 2 ਏਕੜ ਜਾਂ 200 ਏਕੜ ਹੋਵੇ, ਕ੍ਰਿਸ਼ੀ ਸੰਗਮ ਸਕੇਲੇਬਲ ਡਿਜੀਟਲ ਹੱਲਾਂ ਨਾਲ ਹਰ ਆਕਾਰ ਦੇ ਫਾਰਮਾਂ ਦਾ ਸਮਰਥਨ ਕਰਨ ਲਈ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ।',
  'home.why6Title': 'ਵਰਤਣ ਵਿੱਚ ਆਸਾਨ',
  'home.why6Body': 'ਸਧਾਰਨ ਨੇਵੀਗੇਸ਼ਨ, ਸਾਫ਼ ਇੰਟਰਫੇਸ ਅਤੇ ਮੋਬਾਈਲ-ਅਨੁਕੂਲ ਡਿਜ਼ਾਈਨ ਪਲੇਟਫਾਰਮ ਨੂੰ ਵੱਖ-ਵੱਖ ਡਿਜੀਟਲ ਅਨੁਭਵ ਵਾਲੇ ਕਿਸਾਨਾਂ ਲਈ ਪਹੁੰਚਯੋਗ ਬਣਾਉਂਦਾ ਹੈ।',
