  'chatbot.faq1_q': 'What is Krishi Sangam?',
  'chatbot.faq1_a': 'Krishi Sangam is a digital agricultural platform connecting farmers with landowners, equipment providers, labourers, and buyers — all in one place. We make farming simpler, faster, and more accessible.',
  'chatbot.faq2_q': 'Is the platform free to use?',
  'chatbot.faq2_a': 'Yes! Signing up and browsing services on Krishi Sangam is completely free. You only pay when you book a service or make a transaction.',
  'chatbot.faq3_q': 'How do I lease land?',
  'chatbot.faq3_a': 'You can browse available land listings on our Land Leasing page. Each listing shows the area, soil type, water source, and lease terms. Contact the landowner directly through the details provided.',
  'chatbot.faq4_q': 'Can I rent farm equipment?',
  'chatbot.faq4_a': 'Absolutely! Our Equipment Rental section lists tractors, harvesters, rotavators, sprayers, and more from verified owners. You can filter by type and see prices per hour or per day.',
  'chatbot.faq5_q': 'How do I hire farm labour?',
  'chatbot.faq5_a': 'Visit our Agricultural Services page to book a labour team. You can specify the number of workers, days, skill level, and team type. We also have individual service listings for specialised tasks.',
  'chatbot.faq6_q': 'How are my transactions protected?',
  'chatbot.faq6_a': 'Krishi Sangam uses an escrow system for payments. Your payment is held securely until the service is completed, ensuring both parties are protected. We also have a trust-based deposit system that rewards frequent renters with reduced deposits.',
  'chatbot.faq6_f1_q': 'What is the trust deposit system?',
  'chatbot.faq6_f1_a': 'Our trust system has three tiers: New User (full deposit), Trusted (50% deposit after 3 rentals), and Priority (priority bookings after 10 rentals). Each successful rental improves your tier and reduces your deposit requirements.',
  'chatbot.faq6_f2_q': 'How does escrow work?',
  'chatbot.faq6_f2_a': 'When you make a booking, your payment is held in escrow — a secure third-party account. The payment is only released to the service provider once both parties confirm the work is completed. This protects both you and the provider.',
  'chatbot.faq7_q': 'How do I sell my produce?',
  'chatbot.faq7_a': 'You can list your crops on our Produce Marketplace. Add crop details, quantity, grade, and price. Buyers can browse listings and contact you directly through the platform.',
  'chatbot.faq8_q': 'Where can I buy fresh produce?',
  'chatbot.faq8_a': 'Browse our Produce Marketplace to find fresh crops listed directly by farmers. You can filter by crop type, grade, and location to find what you need.',
  'chatbot.faq9_q': 'How do I create an account?',
  'chatbot.faq9_a': 'Click the "Sign Up" button on the top right. Choose your role (Farmer, Land/Equipment Owner, or Labourer), fill in your details, verify your phone number, and you\'re all set!',
  'chatbot.faq10_q': 'Is my personal information safe?',
  'chatbot.faq10_a': 'Yes, we take your privacy seriously. All user data is encrypted and stored securely. We never share your personal information without your consent. See our Terms & Conditions for full details.',
  'chatbot.faq11_q': 'How can I contact support?',
  'chatbot.faq11_a': 'You can reach us at +91-8828473778 or email jaijaikuber@gmail.com. Our registered office is at S.No. 192/2A & 2B, Cosmos, Horizen, Pokharan Road No. 2, Wagle Industrial Estate, Thane – 400604, Maharashtra.',
  'chatbot.faq11_f1_q': 'What are your support hours?',
  'chatbot.faq11_f1_a': 'Our support team is available Monday to Saturday, 9 AM to 6 PM IST. You can also send us an email anytime and we will get back to you within 24 hours.',
  'chatbot.faq12_q': 'How do I check my bookings?',
  'chatbot.faq12_a': 'Go to the "My Bookings" page from your profile menu. You can see all your bookings, their status (Pending, Confirmed, Active, Completed, or Cancelled), and manage them from there.',
  'chatbot.faq13_q': 'How do I list my land?',
  'chatbot.faq13_a': 'Go to the "List Your Land" page and fill in the details: title, area, soil type, water source, lease type, price, and location. Upload a photo for better visibility. Your listing will be reviewed by admin before going live.',
  'chatbot.faq14_q': 'How do I list my equipment?',
  'chatbot.faq14_a': 'Visit the "List Equipment" page and fill in the details: name, type, price per hour/day, and whether you provide an operator. Adding a photo helps attract more renters. A refundable deposit can be set for security.',
